namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious traditional Italian pizza with fresh basil and mozzarella.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch the dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until the crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil before serving."
                ],
                Ratings = [5, 4, 5, 5, 4]
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, cumin, and turmeric for at least 1 hour.",
                    "Grill or broil the marinated chicken until charred and cooked through.",
                    "Sauté diced onion, garlic, and ginger in oil until softened.",
                    "Add tomato sauce and remaining spices, simmer for 15 minutes.",
                    "Stir in heavy cream and the cooked chicken pieces.",
                    "Simmer for 10 more minutes and serve with basmati rice or naan."
                ],
                Ratings = [5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A rich Roman pasta dish with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "While pasta cooks, fry pancetta until crispy.",
                    "Whisk eggs with grated Pecorino Romano and plenty of black pepper.",
                    "Drain pasta, reserving some cooking water.",
                    "Toss hot pasta with pancetta, then quickly stir in the egg mixture off heat.",
                    "Add cooking water as needed to create a creamy sauce. Serve immediately."
                ],
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 4, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
                Steps = [
                    "Brown the ground beef with diced onion in a skillet.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm taco shells in the oven for 3 minutes.",
                    "Fill shells with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, and sour cream."
                ],
                Ratings = [4, 4, 5, 3, 4]
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Thai",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Green onion", "Garlic"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and sugar to make the sauce.",
                    "Stir-fry shrimp and garlic in a hot wok until pink. Set aside.",
                    "Scramble eggs in the wok, then add noodles and sauce.",
                    "Toss until noodles are tender, then add shrimp back in.",
                    "Serve topped with crushed peanuts, bean sprouts, green onion, and lime wedges."
                ],
                Ratings = [5, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit the avocados, scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Soup", Category = "Japanese",
                Description = "A light and warming Japanese soup with tofu and seaweed.",
                Ingredients = ["Dashi stock", "Miso paste", "Silken tofu", "Wakame seaweed", "Green onion"],
                Steps = [
                    "Bring dashi stock to a gentle simmer in a pot.",
                    "Rehydrate wakame seaweed in water for 5 minutes, then drain.",
                    "Dice tofu into small cubes.",
                    "Dissolve miso paste in a ladle of warm dashi, then stir into the pot.",
                    "Add tofu and wakame. Heat gently — do not boil.",
                    "Serve garnished with sliced green onion."
                ],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Grease and flour two ramekins.",
                    "Melt chocolate and butter together, then let cool slightly.",
                    "Whisk eggs, sugar, and vanilla until thick and pale.",
                    "Fold the chocolate mixture into the eggs, then gently fold in flour.",
                    "Divide batter between ramekins and bake for 12–14 minutes.",
                    "Let rest 1 minute, then invert onto plates and serve immediately."
                ],
                Ratings = [5, 5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 9, Title = "Green Curry", Category = "Thai",
                Description = "Aromatic Thai green curry with vegetables and coconut milk.",
                Ingredients = ["Green curry paste", "Coconut milk", "Chicken thighs", "Bamboo shoots", "Thai basil", "Fish sauce", "Palm sugar", "Thai eggplant"],
                Steps = [
                    "Heat coconut cream (thick top layer) in a wok until it splits.",
                    "Add green curry paste and fry until fragrant.",
                    "Add sliced chicken and cook until no longer pink.",
                    "Pour in remaining coconut milk, bamboo shoots, and eggplant.",
                    "Season with fish sauce and palm sugar. Simmer for 15 minutes.",
                    "Stir in Thai basil and serve over jasmine rice."
                ],
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 10, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian layered dessert with coffee-soaked ladyfingers and mascarpone cream.",
                Ingredients = ["Ladyfingers", "Mascarpone cheese", "Eggs", "Sugar", "Espresso", "Cocoa powder", "Marsala wine"],
                Steps = [
                    "Brew espresso and mix with Marsala wine. Let cool.",
                    "Separate eggs. Whisk yolks with sugar until pale and thick.",
                    "Fold mascarpone into the yolk mixture until smooth.",
                    "Beat egg whites to stiff peaks and gently fold into the mascarpone mixture.",
                    "Dip ladyfingers briefly in the espresso mixture and layer in a dish.",
                    "Spread half the cream over the ladyfingers. Repeat layers.",
                    "Refrigerate for at least 4 hours. Dust with cocoa powder before serving."
                ],
                Ratings = [5, 5, 4, 5]
            }
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
            recipe.Ratings.Add(stars);
    }

    public void AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = description,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

