@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — Recipe Community</PageTitle>

<nav class="breadcrumb">
    <a href="/">Home</a> &rsaquo; <span>@CategoryName</span>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a class="recipe-card" href="/recipe/@recipe.Id">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <div class="recipe-meta">
                    <span class="stars">@RenderStars(recipe.AverageRating) (@recipe.RatingCount)</span>
                    <span class="ingredient-count">@recipe.Ingredients.Count ingredients</span>
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        CategoryName = Uri.UnescapeDataString(CategoryName);
        Recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)rating;
        bool half = rating - full >= 0.5;
        var stars = new string('★', full);
        if (half) stars += "½";
        return stars + new string('☆', 5 - full - (half ? 1 : 0));
    }
}

