arguments.file_text:
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    <div class="stars-row">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= HoverStar ? "hovered" : "") @(star <= SelectedStar ? "selected" : "")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => HoverStar = star"
                    @onmouseout="() => HoverStar = 0"
                    title="Rate @star star@(star > 1 ? "s" : "")">
                @(star <= (HoverStar > 0 ? HoverStar : SelectedStar) ? "★" : "☆")
            </button>
        }
    </div>
    @if (Submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    <span class="rating-summary">@Average ★ (@Count ratings)</span>
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }

    private int HoverStar;
    private int SelectedStar;
    private bool Submitted;
    private double Average;
    private int Count;

    protected override void OnParametersSet() => RefreshStats();

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        SelectedStar = stars;
        Submitted = true;
        RefreshStats();
    }

    private void RefreshStats()
    {
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            Average = recipe.AverageRating;
            Count = recipe.RatingCount;
        }
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.8rem;
    flex-wrap: wrap;
    margin: 0.5rem 0 1rem 0;
}

.stars-row {
    display: flex;
    gap: 0.1rem;
}

.star-btn {
    background: none;
    border: none;
    font-size: 1.6rem;
    cursor: pointer;
    color: #ccc;
    padding: 0;
    line-height: 1;
    transition: color 0.15s, transform 0.15s;
}

.star-btn.selected,
.star-btn.hovered {
    color: #f5a623;
}

.star-btn:hover {
    transform: scale(1.2);
}

.rating-thanks {
    color: #2d6a4f;
    font-weight: 600;
    font-size: 0.9rem;
}

.rating-summary {
    color: #888;
    font-size: 0.9rem;
}

@page "/submit"
@using RecipeCommunity.Services
@rendermode InteractiveServer
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmittedSuccessfully)
{
    <div class="success-message">
        <h2>🎉 Recipe Submitted!</h2>
        <p>Your recipe "<strong>@Title</strong>" has been added. <a href="/category/@Uri.EscapeDataString(Category)">View it in @Category</a>.</p>
        <button class="btn btn-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm FormName="submitRecipe" Model="this" OnValidSubmit="HandleSubmit">
        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="Title" placeholder="e.g. Grandma's Apple Pie" required />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="Category">
                <option value="">— Select a category —</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="description">Short Description</label>
            <InputTextArea id="description" @bind-Value="Description" placeholder="A brief description of your recipe" rows="2" />
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="IngredientsText" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" rows="6" required />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="StepsText" placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Combine and bake for 30 minutes." rows="6" required />
        </div>

        <button type="submit" class="btn btn-primary" disabled="@(!IsValid)">Submit Recipe</button>
    </EditForm>
}

@code {
    private string Title { get; set; } = string.Empty;
    private string Category { get; set; } = string.Empty;
    private string Description { get; set; } = string.Empty;
    private string IngredientsText { get; set; } = string.Empty;
    private string StepsText { get; set; } = string.Empty;
    private bool SubmittedSuccessfully { get; set; }

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(Title)
        && !string.IsNullOrWhiteSpace(Category)
        && !string.IsNullOrWhiteSpace(IngredientsText)
        && !string.IsNullOrWhiteSpace(StepsText);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var ingredients = IngredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();
        var steps = StepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        RecipeService.AddRecipe(Title, Category, Description, ingredients, steps);
        SubmittedSuccessfully = true;
    }

    private void ResetForm()
    {
        Title = string.Empty;
        Category = string.Empty;
        Description = string.Empty;
        IngredientsText = string.Empty;
        StepsText = string.Empty;
        SubmittedSuccessfully = false;
    }
}

.success-message {
    background: #d4edda;
    border: 1px solid #c3e6cb;
    border-radius: 10px;
    padding: 1.5rem 2rem;
    margin: 1rem 0;
}

.success-message h2 {
    margin-top: 0;
}

.success-message a {
    color: #2d6a4f;
    font-weight: 600;
}

.form-group {
    margin-bottom: 1.2rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.3rem;
    color: #333;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 1rem;
    font-family: inherit;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2d6a4f;
    box-shadow: 0 0 0 3px rgba(45, 106, 79, 0.15);
}

.btn {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary {
    background: #2d6a4f;
    color: white;
}

.btn-primary:hover:not(:disabled) {
    background: #1b4332;
}

.btn-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    margin-top: 0.5rem;
